css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader::after { content: ''; position: absolute; top: 50%; left: 50%; width: 14%; height: 14%; transform: translate(-50%, -50%); border-radius: 50%; background: var(--accent); z-index: 2; }
.loader .fan { position: relative; width: 82%; height: 82%; animation: spin calc(var(--loader-speed) * .55) linear infinite; }
.loader .fan span { position: absolute; top: 50%; left: 50%; width: 44%; height: 17%; margin-top: -8.5%; background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 60%, var(--accent-2)), var(--accent-2)); border-radius: 30% 60% 60% 30%; transform-origin: left center; }
.loader .fan span:nth-child(1) { transform: rotate(0deg); }
.loader .fan span:nth-child(2) { transform: rotate(120deg); }
.loader .fan span:nth-child(3) { transform: rotate(240deg); }
@keyframes spin { to { transform: rotate(360deg); } }
